    47  /**
    48   * \ingroup strvector
    49   * \function igraph_strvector_init
    50   * \brief Initialize
    51   *
    52   * Reserves memory for the string vector, a string vector must be
    53   * first initialized before calling other functions on it.
    54   * All elements of the string vector are set to the empty string.
    55   * \param sv Pointer to an initialized string vector.
    56   * \param len The (initial) length of the string vector.
    57   * \return Error code.
    58   *
    59   * Time complexity: O(\p len).
    60   */
    61
    62  int igraph_strvector_init(igraph_strvector_t *sv, long int len) {
    63      long int i;
    64      sv->data = igraph_Calloc(len, char*);
    65      if (sv->data == 0) {
    66          IGRAPH_ERROR("strvector init failed", IGRAPH_ENOMEM);
    67      }
    68      for (i = 0; i < len; i++) {
    69          sv->data[i] = igraph_Calloc(1, char);
    70          if (sv->data[i] == 0) {
    71              igraph_strvector_destroy(sv);
    72              IGRAPH_ERROR("strvector init failed", IGRAPH_ENOMEM);
    73          }
    74          sv->data[i][0] = '\0';
    75      }
    76      sv->len = len;
    77
    78      return 0;
    79  }
