    81  /**
    82   * \ingroup strvector
    83   * \function igraph_strvector_destroy
    84   * \brief Free allocated memory
    85   *
    86   * Destroy a string vector. It may be reinitialized with \ref
    87   * igraph_strvector_init() later.
    88   * \param sv The string vector.
    89   *
    90   * Time complexity: O(l), the total length of the strings, maybe less
    91   * depending on the memory manager.
    92   */
    93
    94  void igraph_strvector_destroy(igraph_strvector_t *sv) {
    95      long int i;
    96      IGRAPH_ASSERT(sv != 0);
    97      if (sv->data != 0) {
    98          for (i = 0; i < sv->len; i++) {
    99              if (sv->data[i] != 0) {
   100                  igraph_Free(sv->data[i]);
   101              }
   102          }
   103          igraph_Free(sv->data);
   104      }
   105  }
