   130  /**
   131   * \ingroup strvector
   132   * \function igraph_strvector_set
   133   * \brief Set an element
   134   *
   135   * The provided \p value is copied into the \p idx position in the
   136   * string vector.
   137   * \param sv The string vector.
   138   * \param idx The position to set.
   139   * \param value The new value.
   140   * \return Error code.
   141   *
   142   * Time complexity: O(l), the length of the new string. Maybe more,
   143   * depending on the memory management, if reallocation is needed.
   144   */
   145
   146  int igraph_strvector_set(igraph_strvector_t *sv, long int idx,
   147                           const char *value) {
   148      IGRAPH_ASSERT(sv != 0);
   149      IGRAPH_ASSERT(sv->data != 0);
   150      if (sv->data[idx] == 0) {
   151          sv->data[idx] = igraph_Calloc(strlen(value) + 1, char);
   152          if (sv->data[idx] == 0) {
   153              IGRAPH_ERROR("strvector set failed", IGRAPH_ENOMEM);
   154          }
   155      } else {
   156          char *tmp = igraph_Realloc(sv->data[idx], strlen(value) + 1, char);
   157          if (tmp == 0) {
   158              IGRAPH_ERROR("strvector set failed", IGRAPH_ENOMEM);
   159          }
   160          sv->data[idx] = tmp;
   161      }
   162      strcpy(sv->data[idx], value);
   163
   164      return 0;
   165  }
