   170   * \brief Sets an element
   171   *
   172   * This is almost the same as \ref igraph_strvector_set, but the new
   173   * value is not a zero terminated string, but its length is given.
   174   * \param sv The string vector.
   175   * \param idx The position to set.
   176   * \param value The new value.
   177   * \param len The length of the new value.
   178   * \return Error code.
   179   *
   180   * Time complexity: O(l), the length of the new string. Maybe more,
   181   * depending on the memory management, if reallocation is needed.
   182   */
   183  int igraph_strvector_set2(igraph_strvector_t *sv, long int idx,
   184                            const char *value, int len) {
   185      IGRAPH_ASSERT(sv != 0);
   186      IGRAPH_ASSERT(sv->data != 0);
   187      if (sv->data[idx] == 0) {
   188          sv->data[idx] = igraph_Calloc(len + 1, char);
   189          if (sv->data[idx] == 0) {
   190              IGRAPH_ERROR("strvector set failed", IGRAPH_ENOMEM);
   191          }
   192      } else {
   193          char *tmp = igraph_Realloc(sv->data[idx], (size_t) len + 1, char);
   194          if (tmp == 0) {
   195              IGRAPH_ERROR("strvector set failed", IGRAPH_ENOMEM);
   196          }
   197          sv->data[idx] = tmp;
   198      }
   199      memcpy(sv->data[idx], value, (size_t) len * sizeof(char));
   200      sv->data[idx][len] = '\0';
   201
   202      return 0;
   203  }
